import Foundation

struct ConversationStore {
    private let defaults = UserDefaults.standard
    private let prefix = "conversation."

    func load(mode: CreatorMode) -> [ChatMessage] {
        guard let data = defaults.data(forKey: prefix + mode.rawValue) else { return [] }
        return (try? JSONDecoder().decode([ChatMessage].self, from: data)) ?? []
    }

    func save(_ messages: [ChatMessage], mode: CreatorMode) {
        guard let data = try? JSONEncoder().encode(messages) else { return }
        defaults.set(data, forKey: prefix + mode.rawValue)
    }

    func clear(mode: CreatorMode) {
        defaults.removeObject(forKey: prefix + mode.rawValue)
    }
}

