import Foundation

struct WorkspaceFileReader {
    let maxCharacters = 20_000

    func readTextFile(url: URL) throws -> AttachedFile {
        let data = try Data(contentsOf: url)
        guard let raw = String(data: data, encoding: .utf8) ?? String(data: data, encoding: .utf16) else {
            throw FileReadError.unsupportedEncoding
        }

        let content: String
        let wasTruncated: Bool
        if raw.count > maxCharacters {
            content = String(raw.prefix(maxCharacters))
            wasTruncated = true
        } else {
            content = raw
            wasTruncated = false
        }

        return AttachedFile(
            name: url.lastPathComponent,
            path: url.path,
            content: content,
            wasTruncated: wasTruncated
        )
    }
}

struct AttachedFile: Codable, Equatable {
    let name: String
    let path: String
    let content: String
    let wasTruncated: Bool
}

enum FileReadError: LocalizedError {
    case unsupportedEncoding

    var errorDescription: String? {
        "这个文件不是可读取的文本文件。"
    }
}

import Foundation

struct DeepSeekClient {
    var endpoint = URL(string: "https://api.deepseek.com/chat/completions")!

    func send(apiKey: String, model: String, messages: [ChatMessage]) async throws -> String {
        var request = URLRequest(url: endpoint)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
        request.timeoutInterval = 60

        let body = ChatCompletionRequest(
            model: model,
            messages: messages.map { ChatCompletionMessage(role: $0.role.rawValue, content: $0.content) },
            temperature: 0.7
        )
        request.httpBody = try JSONEncoder().encode(body)

        let (data, response) = try await URLSession.shared.data(for: request)
        guard let httpResponse = response as? HTTPURLResponse else {
            throw DeepSeekError.invalidResponse
        }

        guard (200..<300).contains(httpResponse.statusCode) else {
            let details = String(data: data, encoding: .utf8) ?? "No response body"
            throw DeepSeekError.http(status: httpResponse.statusCode, details: details)
        }

        let decoded = try JSONDecoder().decode(ChatCompletionResponse.self, from: data)
        guard let content = decoded.choices.first?.message.content, !content.isEmpty else {
            throw DeepSeekError.emptyResponse
        }
        return content
    }
}

enum DeepSeekError: LocalizedError {
    case invalidResponse
    case emptyResponse
    case http(status: Int, details: String)

    var errorDescription: String? {
        switch self {
        case .invalidResponse:
            return "DeepSeek 返回格式不正确。"
        case .emptyResponse:
            return "DeepSeek 没有返回内容。"
        case .http(let status, let details):
            return "DeepSeek 请求失败：HTTP \(status)。\(details)"
        }
    }
}

private struct ChatCompletionRequest: Encodable {
    let model: String
    let messages: [ChatCompletionMessage]
    let temperature: Double
}

private struct ChatCompletionMessage: Codable {
    let role: String
    let content: String
}

private struct ChatCompletionResponse: Decodable {
    struct Choice: Decodable {
        struct Message: Decodable {
            let role: String
            let content: String
        }

        let message: Message
    }

    let choices: [Choice]
}

