import Foundation
import Security

struct KeychainStore {
    private let service = "KidCreatorMac.DeepSeek"
    private let account = "deepseek-api-key"

    func save(_ value: String) throws {
        let data = Data(value.utf8)
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account
        ]
        let attributes: [String: Any] = [
            kSecValueData as String: data
        ]

        let status = SecItemUpdate(query as CFDictionary, attributes as CFDictionary)
        if status == errSecItemNotFound {
            var newItem = query
            newItem[kSecValueData as String] = data
            let addStatus = SecItemAdd(newItem as CFDictionary, nil)
            guard addStatus == errSecSuccess else { throw KeychainError.unhandled(addStatus) }
        } else if status != errSecSuccess {
            throw KeychainError.unhandled(status)
        }
    }

    func load() throws -> String {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecReturnData as String: true,
            kSecMatchLimit as String: kSecMatchLimitOne
        ]

        var item: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &item)
        if status == errSecItemNotFound { return "" }
        guard status == errSecSuccess, let data = item as? Data else {
            throw KeychainError.unhandled(status)
        }
        return String(data: data, encoding: .utf8) ?? ""
    }
}

enum KeychainError: LocalizedError {
    case unhandled(OSStatus)

    var errorDescription: String? {
        switch self {
        case .unhandled(let status):
            return "Keychain 操作失败：\(status)"
        }
    }
}

import Foundation

struct ChatMessage: Identifiable, Codable, Equatable {
    enum Role: String, Codable {
        case user
        case assistant
        case system
    }

    var id = UUID()
    var role: Role
    var content: String
    var createdAt = Date()
}

import Foundation

@MainActor
final class AppStore: ObservableObject {
    @Published var selectedMode: CreatorMode = .chat {
        didSet { messages = conversationStore.load(mode: selectedMode) }
    }
    @Published var messages: [ChatMessage] = []
    @Published var draft = ""
    @Published var apiKey = ""
    @Published var model = "deepseek-chat"
    @Published var statusText = "请输入 DeepSeek API Key"
    @Published var isSending = false
    @Published var attachedFile: AttachedFile?
    @Published var lastError: String?

    private let client = DeepSeekClient()
    private let keychain = KeychainStore()
    private let conversationStore = ConversationStore()

    var canSend: Bool {
        !apiKey.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty &&
        !draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty &&
        !isSending
    }

    init() {
        apiKey = (try? keychain.load()) ?? ""
        statusText = apiKey.isEmpty ? "请输入 DeepSeek API Key" : "DeepSeek Key 已保存"
        messages = conversationStore.load(mode: selectedMode)
    }

    func saveAPIKey() {
        do {
            try keychain.save(apiKey.trimmingCharacters(in: .whitespacesAndNewlines))
            statusText = "DeepSeek Key 已保存到 Keychain"
            lastError = nil
        } catch {
            lastError = error.localizedDescription
        }
    }

    func validateAPIKey() async {
        saveAPIKey()
        guard !apiKey.isEmpty else { return }
        isSending = true
        defer { isSending = false }

        do {
            _ = try await client.send(
                apiKey: apiKey,
                model: model,
                messages: [
                    ChatMessage(role: .system, content: "Reply with a short Chinese confirmation."),
                    ChatMessage(role: .user, content: "请回复：连接成功。")
                ]
            )
            statusText = "DeepSeek 连接成功"
            lastError = nil
        } catch {
            lastError = error.localizedDescription
            statusText = "DeepSeek 连接失败"
        }
    }

    func useStarter(_ card: PromptCard) {
        draft = card.prompt
    }

    func attachFile(_ file: AttachedFile) {
        attachedFile = file
        if draft.isEmpty {
