import Foundation

enum ModelProvider: String, CaseIterable, Identifiable, Codable {
    case deepseek
    case minimax
    case kimi

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .deepseek: "DeepSeek"
        case .minimax: "MiniMax"
        case .kimi: "Kimi"
        }
    }

    var baseURL: URL {
        switch self {
        case .deepseek:
            URL(string: "https://api.deepseek.com")!
        case .minimax:
            URL(string: "https://api.minimax.io/v1")!
        case .kimi:
            URL(string: "https://api.moonshot.ai/v1")!
        }
    }

    var chatCompletionsURL: URL {
        baseURL.appendingPathComponent("chat/completions")
    }

    var defaultModel: String {
        switch self {
        case .deepseek: "deepseek-chat"
        case .minimax: "MiniMax-M2.7"
        case .kimi: "kimi-k2.6"
        }
    }

    var keyPlaceholder: String {
        switch self {
        case .deepseek: "DeepSeek API Key"
        case .minimax: "MiniMax API Key"
        case .kimi: "Kimi / Moonshot API Key"
        }
    }
}

