import AppKit
import Foundation

struct ArtifactExporter {
    private let folderName = "Kid Creator Works"

    func export(content: String, mode: CreatorMode) throws -> WorkArtifact {
        let root = try worksRoot()
        let title = titleFrom(content: content, mode: mode)
        let slug = slugify(title)
        let timestamp = Self.timestampFormatter.string(from: Date())
        let folder = root.appendingPathComponent("\(timestamp)-\(slug)", isDirectory: true)
        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)

        let fileURL: URL
        let fileContent: String
        switch mode {
        case .website:
            fileURL = folder.appendingPathComponent("index.html")
            fileContent = extractHTML(from: content) ?? fallbackHTML(title: title, body: content)
        case .slides:
            let markdownURL = folder.appendingPathComponent("presentation.md")
            let markdown = """
            # \(title)

            > 这是 Kid Creator 保存的 PPT 制作方案。下一步可以交给本地 PPT Skill 生成 .pptx。

            \(content)
            """
            try markdown.write(to: markdownURL, atomically: true, encoding: .utf8)

            if let deckSpec = extractJSONBlock(from: content) {
                let specURL = folder.appendingPathComponent("deck-spec.json")
                try deckSpec.write(to: specURL, atomically: true, encoding: .utf8)
            }

            fileURL = folder.appendingPathComponent("slides-preview.html")
            fileContent = slidesPreviewHTML(title: title, body: content)
        case .code:
            fileURL = folder.appendingPathComponent("code-notes.md")
            fileContent = "# \(title)\n\n\(content)"
        case .chat:
            fileURL = folder.appendingPathComponent("learning-notes.md")
            fileContent = "# \(title)\n\n\(content)"
        }

        try fileContent.write(to: fileURL, atomically: true, encoding: .utf8)
        return WorkArtifact(title: title, url: fileURL, mode: mode, createdAt: Date())
    }

    func reveal(_ artifact: WorkArtifact) {
        NSWorkspace.shared.activateFileViewerSelecting([artifact.url])
    }

    func open(_ artifact: WorkArtifact) {
        NSWorkspace.shared.open(artifact.url)
    }

    private func worksRoot() throws -> URL {
        let documents = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first
            ?? FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Documents", isDirectory: true)
        let root = documents.appendingPathComponent(folderName, isDirectory: true)
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        return root
    }

    private func titleFrom(content: String, mode: CreatorMode) -> String {
        for line in content.components(separatedBy: .newlines) {
            let trimmed = line.trimmingCharacters(in: .whitespacesAndNewlines)
            if trimmed.hasPrefix("# ") {
                return String(trimmed.dropFirst(2)).trimmingCharacters(in: .whitespacesAndNewlines)
            }
            if trimmed.hasPrefix("标题：") {
                return String(trimmed.dropFirst(3)).trimmingCharacters(in: .whitespacesAndNewlines)
            }
            if trimmed.hasPrefix("Title:") {
                return String(trimmed.dropFirst(6)).trimmingCharacters(in: .whitespacesAndNewlines)
            }
        }

        switch mode {
        case .chat: return "学习笔记"
        case .slides: return "我的演示稿"
        case .website: return "我的网页"
        case .code: return "代码学习笔记"
        }
    }

    private func slugify(_ value: String) -> String {
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "-_"))
        let folded = value.folding(options: [.diacriticInsensitive, .widthInsensitive], locale: .current)
        let scalars = folded.unicodeScalars.map { allowed.contains($0) ? Character($0) : "-" }
        let slug = String(scalars)
            .replacingOccurrences(of: "--", with: "-")
            .trimmingCharacters(in: CharacterSet(charactersIn: "-"))
        return slug.isEmpty ? "work" : String(slug.prefix(48))
    }

    private func extractHTML(from content: String) -> String? {
        let fenceMarkers = ["```html", "```HTML", "```"]
        for marker in fenceMarkers {
            guard let start = content.range(of: marker) else { continue }
            let bodyStart = start.upperBound
            guard let end = content[bodyStart...].range(of: "```") else { continue }
            let candidate = String(content[bodyStart..<end.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines)
            if candidate.localizedCaseInsensitiveContains("<html") || candidate.localizedCaseInsensitiveContains("<!doctype html") {
                return candidate
            }
        }

        if let docType = content.range(of: "<!doctype html", options: .caseInsensitive) {
            return String(content[docType.lowerBound...]).trimmingCharacters(in: .whitespacesAndNewlines)
        }

        if let htmlStart = content.range(of: "<html", options: .caseInsensitive) {
            return String(content[htmlStart.lowerBound...]).trimmingCharacters(in: .whitespacesAndNewlines)
        }

        return nil
    }

    private func extractJSONBlock(from content: String) -> String? {
        let markers = ["```json", "```JSON", "```deck_spec", "```deck-spec"]
        for marker in markers {
            guard let start = content.range(of: marker) else { continue }
            let bodyStart = start.upperBound
            guard let end = content[bodyStart...].range(of: "```") else { continue }
            let candidate = String(content[bodyStart..<end.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines)
            if candidate.hasPrefix("{"), candidate.hasSuffix("}") {
                return candidate
            }
        }

        guard let firstBrace = content.firstIndex(of: "{"),
              let lastBrace = content.lastIndex(of: "}"),
              firstBrace < lastBrace
        else {
            return nil
        }

        let candidate = String(content[firstBrace...lastBrace]).trimmingCharacters(in: .whitespacesAndNewlines)
        guard candidate.contains("\"slides\"") else { return nil }
        return candidate
    }

    private func fallbackHTML(title: String, body: String) -> String {
        let escapedTitle = escapeHTML(title)
        let escapedBody = escapeHTML(body)
        return """
        <!doctype html>
        <html lang="zh-CN">
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>\(escapedTitle)</title>
          <style>
            body { font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif; margin: 0; background: #f6f7fb; color: #20242c; }
            main { max-width: 880px; margin: 0 auto; padding: 48px 24px; }
