          </style>
        </head>
        <body>
          <main>
            <article>
              <h1>\(escapedTitle)</h1>
              <pre>\(escapedBody)</pre>
            </article>
          </main>
        </body>
        </html>
        """
    }

    private func slidesPreviewHTML(title: String, body: String) -> String {
        let escapedTitle = escapeHTML(title)
        let sections = body
            .components(separatedBy: "\n## ")
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }

        let slides: String
        if sections.count > 1 {
            slides = sections.map { section in
                """
                <section class="slide">
                  <pre>\(escapeHTML(section))</pre>
                </section>
                """
            }.joined(separator: "\n")
        } else {
            slides = """
            <section class="slide">
              <pre>\(escapeHTML(body))</pre>
            </section>
            """
        }

        return """
        <!doctype html>
        <html lang="zh-CN">
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>\(escapedTitle)</title>
          <style>
            :root { color-scheme: light; }
            body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif; background: #eef2f8; color: #18212f; }
            header { position: sticky; top: 0; z-index: 2; background: rgba(255,255,255,.9); backdrop-filter: blur(18px); border-bottom: 1px solid #d7dde8; padding: 14px 28px; }
            h1 { margin: 0; font-size: 20px; }
            main { display: grid; gap: 24px; max-width: 980px; margin: 0 auto; padding: 28px; }
            .slide { aspect-ratio: 16 / 9; background: linear-gradient(135deg, #ffffff 0%, #f7fbff 100%); border: 1px solid #dce3ee; border-radius: 10px; box-shadow: 0 18px 45px rgba(22, 35, 60, .10); padding: 40px; overflow: auto; }
            pre { margin: 0; white-space: pre-wrap; font: 18px/1.55 -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif; }
          </style>
        </head>
        <body>
          <header><h1>\(escapedTitle)</h1></header>
          <main>
            \(slides)
          </main>
        </body>
        </html>
        """
    }

    private func escapeHTML(_ value: String) -> String {
        value
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
    }

    private static let timestampFormatter: DateFormatter = {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyyMMdd-HHmmss"
        return formatter
    }()
