        let json = try extractJSONObject(from: raw)
        let data = Data(json.utf8)
        var spec = try JSONDecoder().decode(SlideDeckSpec.self, from: data)
        spec = spec.normalized()
        try spec.validate()
        return spec
    }

    func prettyJSONString() throws -> String {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]
        let data = try encoder.encode(self)
        return String(data: data, encoding: .utf8) ?? "{}"
    }

    func chatSummary() -> String {
        let lines = slides.enumerated().map { index, slide in
            "\(index + 1). \(slide.title)"
        }.joined(separator: "\n")

        return """
        已生成 PPT 内容结构：\(title)

        \(lines)

        正在把结构化内容交给本地 PPT skill 生成 PowerPoint 文件。
        """
    }

    private func normalized() -> SlideDeckSpec {
        let fixedSlides = slides.enumerated().map { index, slide in
            var fixed = slide
            if fixed.type == nil {
                fixed.type = index == 0 ? "title_dark" : "bullets"
            }
            if fixed.type == "cover" || fixed.layout == "cover" {
                fixed.type = "title_dark"
            }
            if fixed.type == "closing" || fixed.layout == "closing" {
                fixed.type = "closing"
            }
            fixed.title = fixed.title.trimmingCharacters(in: .whitespacesAndNewlines)
            fixed.subtitle = fixed.subtitle?.trimmingCharacters(in: .whitespacesAndNewlines)
            fixed.body = fixed.body?.trimmingCharacters(in: .whitespacesAndNewlines)
            fixed.bullets = fixed.bullets?.map { trimForSlide($0, maxLength: 42) }.filter { !$0.isEmpty }
            fixed.speakerNotes = fixed.speakerNotes ?? fixed.notes
            return fixed
        }

        return SlideDeckSpec(
            title: title.trimmingCharacters(in: .whitespacesAndNewlines),
            audience: audience,
            style: style,
            author: author ?? "Kid Creator",
            footerText: footerText ?? "Kid Creator",
            slides: fixedSlides
        )
    }

    private func validate() throws {
        var errors: [String] = []

        if title.isEmpty {
            errors.append("缺少 title")
        }

        if slides.count < 3 || slides.count > 8 {
