            throw SlideDeckSpecError.validation(errors)
        }
    }

    private static func extractJSONObject(from raw: String) throws -> String {
        if let fenced = raw.range(of: #"```(?:json|deck_spec|deck-spec)?\s*([\s\S]*?)```"#, options: .regularExpression) {
            let block = String(raw[fenced])
                .replacingOccurrences(of: #"^```(?:json|deck_spec|deck-spec)?\s*"#, with: "", options: .regularExpression)
                .replacingOccurrences(of: #"```$"#, with: "", options: .regularExpression)
